def test_map_runner_input():
    class MyInput(Input):
        a_str: str
        an_int: int
        a_dict: dict
        a_list: list

    kwargs = {
        "a_str": "hello",
        "an_int": "123",
        "a_dict": '{"a-key": "a-value"}',
        "a_list": json.dumps([1, 2, 3]),
